def find_bounds(lower, upper):
    # Find smallest n >= lower such that n % 4 == 0 or n % 4 == 1
    m = lower
    while m <= upper:
        if m % 4 == 0 or m % 4 == 1:
            break
        m += 1

    # Find largest n <= upper such that n % 4 == 0 or n % 4 == 1
    M = upper
    while M >= lower:
        if M % 4 == 0 or M % 4 == 1:
            break
        M -= 1
    return m, M

m_val, M_val = find_bounds(99, 206)
